# Concept Clustering Engine - runnable demo (JAH-ATK170-000001)
import math
from collections import Counter
RANK = 1
SIG = False
DOCS = [('d1', ['telescope', 'stars', 'orbit']), ('d2', ['planet', 'orbit', 'stars']), ('d3', ['recipe', 'flour', 'oven']), ('d4', ['bake', 'flour', 'sugar'])]  # (doc_id, [terms])
def tfidf_vec(terms, df, n):
    tf = Counter(terms)
    return {t: (c/len(terms)) * math.log(n/df[t]) for t, c in tf.items()}
df = Counter()
for _, terms in DOCS: df.update(set(terms))
vecs = {d: tfidf_vec(ts, df, len(DOCS)) for d, ts in DOCS}
def cos(a, b):
    dot = sum(a.get(t, 0)*b.get(t, 0) for t in set(a) | set(b))
    na, nb = math.sqrt(sum(v*v for v in a.values())), math.sqrt(sum(v*v for v in b.values()))
    return dot/(na*nb) if na and nb else 0.0
ids = list(vecs)
assign = {i: 0 for i in ids}
for _ in range(10):
    c0 = {t: sum(vecs[i].get(t, 0) for i in ids if assign[i] == 0)/max(1, sum(1 for i in ids if assign[i] == 0)) for t in df}
    c1 = {t: sum(vecs[i].get(t, 0) for i in ids if assign[i] == 1)/max(1, sum(1 for i in ids if assign[i] == 1)) for t in df}
    for i in ids: assign[i] = 0 if cos(vecs[i], c0) >= cos(vecs[i], c1) else 1
for k in (0, 1):
    members = [i for i in ids if assign[i] == k]
    lab = Counter()
    for i in members: lab.update(vecs[i])
    print("cluster %d [%s]: %s" % (k, ", ".join(t for t, _ in lab.most_common(3)), members))
if RANK >= 3:
    print("documents clustered:", len(ids))
if SIG:
    print("Signature lineage stamp: JAH-SIG-CLU-" + "JAH-ATK170-000001")
print("record:", "JAH-ATK170-000001", "OK")

